add("LY-425",
"方向：候选可得缺，应期在申月——官鬼申金为得缺之用，不上卦而见于变爻两处：四爻妻财未土化官鬼申金、三爻妻财辰土持世动化官鬼申金，世动而化出官鬼（用神之亲），候选之身动化官，主得缺之象已成形；申金戌月金相有气。父母子水初爻动而旬空，化妻财辰土回头克水（土克水），文书一线动化克主手续有阻、量级打折；上爻兄弟卯木动化父母子水（空），旁线纷扰。应期（月档，候选事）：窗口为数月之内，主坐标申月——官鬼申金逢值且金旺得地之月，得缺落实。",
"tradition: liuyao\n本例卡面 tradition 字段值：liuyao（首行照录见首行）。戌月甲寅日，风雷益之水山蹇（巽宫），空亡子丑（甲寅旬）。卡面无 yongshen 字段，候选得缺以官鬼为用自取。\n用神候选枚举：现卦无官；变爻官鬼申金两现（未化、辰化）——变爻有用神，不取伏神，定变出申金为用神，世化一支为主线（世动化官）、未化一支作同指佐证，去向写明。旺衰：申金戌月相。原神妻财辰未土生金（世辰土动生化）；忌神子孙巳火五爻静克金（戌月火休）。动化方向核对：辰土→申金，土生金化泄而化出用神之亲；未土→申金同；子水→辰土，土克水回头克（父母化克）；卯木→子水，化出父母而空。四路：路1 用神相（变出）0/+；路2 原动生化、忌休静 ＋；路3 动化出用神之亲＋（引裁决表化用定性）；路4 候选兼上位：应兄弟卯木动，世辰土克应？土不克木、木克土应克世 −（只调量级）。合参方向：成。反转扫查：三类俱无（用神取变爻非伏，引拨链不适用）。对象对齐：所问＝候选何时得缺；用神＝变出官鬼申金；应验对象＝求测者所候之缺，同一。应期三步：尺度月档；冲实路申逢寅冲（占日寅冲申为发动据）舍；填实路子丑填父母之空为手续候选舍；逢值路申月官逢值，取。门类对表：对表无候选门类，明写无此门类。应期对决：申日与申月异尺度——闸门无空墓0:0、天然视野候选事以月相符申月＋1、合流申月兼金旺双机制＋1，申月胜。\n第八节功量核（R80-REV1）：做功线清单——世动化官助成（强）、变出官两现同指助成、父母动化回头克压制（手续阻）、子孙休静克官压制（弱）。主线认定：世动化出官鬼为主线。定带：助成居主，等级带中上——断可得缺。\n动化方向：妻财辰土→官鬼申金，化出用神之亲（土生金化泄）；父母子水→妻财辰土，回头克（土克水）。\n反转条件：源绝三征不备，不反转。",
0.60, False, True, False,
"终局未变更，changed_main=false；用神取变爻官鬼申金（变爻有用神优先、备用源启用），故 reserve_used=true；变爻两现同指、取用裁清，disputed=false。")

# ---------------- main ----------------
B11 = ["LY-312","LY-314","LY-315","LY-318","LY-319","LY-320","LY-322","LY-323","LY-324","LY-325",
       "LY-328","LY-329","LY-330","LY-331","LY-332","LY-333","LY-335","LY-336","LY-338","LY-339"]
B12 = ["LY-340","LY-342","LY-344","LY-402","LY-403","LY-404","LY-405","LY-406","LY-407","LY-408",
       "LY-411","LY-413","LY-415","LY-416","LY-417","LY-418","LY-421","LY-423","LY-424","LY-425"]
assert set(DATA.keys()) == set(B11) | set(B12), (set(DATA.keys()) ^ (set(B11) | set(B12)))
assert len(B11) == 20 and len(B12) == 20 and len(DATA) == 40
for cid in B11:
    assert cid in DATA, cid
print("B11 id set OK:", len(B11))
for cid in B12:
    assert cid in DATA, cid
print("B12 id set OK:", len(B12))

written = 0
for cid in B11 + B12:
    rec = DATA[cid]
    if not rec["basis"].startswith("tradition: liuyao"):
        rec["basis"] = "tradition: liuyao\n" + rec["basis"]
    assert "第八节功量核" in rec["basis"] and "主线认定" in rec["basis"], cid
    assert "动化方向" in rec["basis"] and "反转条件" in rec["basis"], cid
    assert set(rec.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, cid
    assert set(rec["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}, cid
    path = os.path.join(BASE, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    written += 1
print("written:", written)

#逐件精确打开自验（只按本批 id 清单逐件打开，不做目录列表/计数）
ok = 0
for cid in B11 + B12:
    with open(os.path.join(BASE, cid + ".json"), encoding="utf-8") as f:
        r = json.load(f)
    assert r["case_id"] == cid and r["basis"].startswith("tradition: liuyao"), cid
    assert 0.0 <= r["confidence"] <= 1.0 and r["prediction_text"], cid
    ok += 1
print("verified per-id:", ok)
cm = sum(1 for c in B11 + B12 if DATA[c]["trigger"]["changed_main"])
ru = sum(1 for c in B11 + B12 if DATA[c]["trigger"]["reserve_used"])
di = sum(1 for c in B11 + B12 if DATA[c]["trigger"]["disputed"])
print("trigger counts changed_main/reserve_used/disputed:", cm, ru, di)
print("reserve_true:", [c for c in B11 + B12 if DATA[c]["trigger"]["reserve_used"]])
print("disputed_true:", [c for c in B11 + B12 if DATA[c]["trigger"]["disputed"]])
